--

CREATE TABLE `sales` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `customer_id` bigint(20) UNSIGNED DEFAULT NULL,
  `total_usd` decimal(20,6) NOT NULL,
  `total_ves` decimal(15,4) NOT NULL,
  `total_cop` decimal(15,4) NOT NULL,
